import math

def K(n):
    # Handle n=0 case where 2n-1 = -1
    if n == 0:
        return 3 * (math.factorial(n+2) + 1) / (2*n - 1)

    # Check for cases where 2n-1 might be 0 (not possible for non-negative n)
    denominator = 2*n - 1
    if denominator == 0:
        return None

    numerator = 3 * (math.factorial(n+2) + 1)
    return numerator / denominator

solutions = []
for n in range(26):
    result = K(n)
    # Check if the result is an integer (within a small floating point tolerance)
    if result is not None and abs(result - round(result)) < 1e-9:
        solutions.append(n)

print(f"Solutions found up to n=25: {solutions}")
